   442  // shift the input buffer to discard one character and reread data
   443  static void character_discard(struct gps_lexer_t *lexer)
   444  {
   445      memmove(lexer->inbuffer, lexer->inbuffer + 1, (size_t)-- lexer->inbuflen);
   446      lexer->inbufptr = lexer->inbuffer;
   447      if (lexer->errout.debug >= LOG_RAW1) {
   448          char scratchbuf[MAX_PACKET_LENGTH*4+1];
   449
   450          GPSD_LOG(LOG_RAW1, &lexer->errout,
   451                   "Character discarded, buffer %zu chars = %s\n",
   452                   lexer->inbuflen,
   453                   gpsd_packetdump(scratchbuf, sizeof(scratchbuf),
   454                                   lexer->inbuffer, lexer->inbuflen));
   455      }
   456  }
