   516              lexer->state = ITALK_LEADER_1;
   517              break;
   518  #endif  // ITRAX_ENABLE
   519  #ifdef TRIPMATE_ENABLE
   520          case 'A':
   521              if (ISGPS_MESSAGE == rtcm2_decode(lexer, c)) {
   522                  lexer->state = RTCM2_RECOGNIZED;
   523                  break;
   524              }
   525              lexer->state = ASTRAL_1;
   526              break;
   527  #endif  // TRIPMATE_ENABLE
   528  #ifdef EARTHMATE_ENABLE
