   530              if (ISGPS_MESSAGE == rtcm2_decode(lexer, c)) {
   531                  lexer->state = RTCM2_RECOGNIZED;
   532                  break;
   533              }
   534              lexer->state = EARTHA_1;
   535              break;
   536  #endif  // EARTHMATE_ENABLE
   537  #ifdef GEOSTAR_ENABLE
   538          case 'P':
   539              lexer->state = GEOSTAR_LEADER_1;
   540              break;
   541  #endif  // GEOSTAR_ENABLE
   542  #ifdef GREIS_ENABLE
